#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    if (!(std::cin >> n)) return 0;

    std::vector<int> a(n);
    for (int i = 0; i < n; ++i) std::cin >> a[i];

    int best = 0;
    for (int i = 0; i < n; ++i) {
        if (i == 0 || a[i] > best) best = a[i];
        std::cout << best << "\n";
    }
    return 0;
}

